package com.ke.ticketsystemke.controller;import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.service.*;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/volt/warranty-reminders")public class WarrantyReminderController{private final WarrantyReminderService service;private final WarrantyReminderGenerationService generation;private final AccessService access;public WarrantyReminderController(WarrantyReminderService s,WarrantyReminderGenerationService g,AccessService a){service=s;generation=g;access=a;}@GetMapping public WarrantyReminderPageResponse list(@ModelAttribute WarrantyReminderFilter f,Authentication a){return service.list(f,a.getName());}@GetMapping("/daily-summary")public WarrantyReminderDailySummary summary(Authentication a){return service.summary(a.getName());}@PostMapping("/{id}/acknowledge")public WarrantyReminderResponse acknowledge(@PathVariable Long id,@Valid @RequestBody WarrantyReminderAcknowledgeRequest r,Authentication a){return service.acknowledge(id,r,a.getName());}@PostMapping("/{id}/snooze")public WarrantyReminderResponse snooze(@PathVariable Long id,@Valid @RequestBody WarrantyReminderSnoozeRequest r,Authentication a){return service.snooze(id,r,a.getName());}@PostMapping("/generate")public WarrantyReminderGenerationResponse generate(Authentication a){var current=access.getCurrentAccess(a.getName());if(!current.superAdmin())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Super Admin access required");return generation.generate();}}
